// demo/frontend/tymc-model.ts
function buildTymcModel(data, config) {
  const columns3 = (names, rows) => Object.fromEntries(
    names.map((name, c) => [name, rows.map((row) => row[c])])
  );
  const raw = mmm_exports.dataset({
    verbose: false,
    dates: data.dates,
    channels: columns3(data.channels, data.x),
    controls: columns3(data.controls, data.z),
    target: data.y
  });
  const scaled2 = mmm_exports.scale(raw, {
    channels: "max",
    target: "max",
    controls: "none"
  });
  const spec2 = mmm_exports.spec({
    media: {
      adstock: mmm_exports.adstock.geometric({ l_max: config.lag, normalize: true }),
      saturation: mmm_exports.saturation.logistic()
    },
    ...config.seasonality ? { seasonality: mmm_exports.fourier.yearly({ order: 2 }) } : {}
  });
  const priors = mmm_exports.override_spec_priors(
    spec2,
    mmm_exports.pymc_marketing_spec_priors(spec2, scaled2),
    {
      "adstock.geometric.alpha": mmm_exports.prior(
        distributions_exports.beta,
        config.adstockPrior ?? { alpha: 1, beta: 3 }
      ),
      "saturation.logistic.lam": mmm_exports.prior(
        distributions_exports.gamma,
        config.saturationPrior ?? { alpha: 3, beta: 1 }
      ),
      "transformed_channel.coefficient": mmm_exports.prior(distributions_exports.half_normal, {
        sigma: config.priorScale
      })
    }
  );
  return { spec: spec2, priors, scaled: scaled2 };
}
function sampleTymcModel(data, config, onPhase = () => {
}, onProgress, onPriorReport = () => {
}) {
  const setup = buildTymcModel(data, config);
  onPhase("Checking the model priors");
  const checked = mmm_exports.check_priors(setup.spec, setup.priors, setup.scaled, {
    verbose: false
  });
  onPriorReport(mmm_exports.format_prior_check(checked));
  const built = mmm_exports.build(setup.spec, setup.priors, setup.scaled);
  onPhase("Compiling TyMC model");
  const compileStart = performance.now();
  const compiled = modeling_exports.compile_model(built.model);
  const alphaTarget = modeling_exports.draw_targets(built.model).find((target) => target.name === "adstock.geometric.alpha");
  const compileSeconds = (performance.now() - compileStart) / 1e3;
  onPhase("Sampling with TyMC");
  const sampleStart = performance.now();
  const chains = sample(compiled.logp_and_grad, {
    draws: config.draws,
    tune: config.tune,
    chains: config.chains,
    target_accept: config.targetAccept,
    seed: config.seed,
    initial_point: modeling_exports.initial_point(built.model).data,
    on_progress: onProgress ? (event) => onProgress(
      event,
      event.phase === "draw" ? modeling_exports.constrain_draw(built.model, event.position, [
        alphaTarget
      ])[0].data[0] : void 0
    ) : void 0,
    progress_every: 1,
    progress_interval_ms: 0
  });
  const samplingSeconds = (performance.now() - sampleStart) / 1e3;
  onPhase("Computing posterior predictions and diagnostics");
  const result = modeling_exports.assemble_result(built.model, chains);
  return {
    fitted: { ...built, prior_check: checked, result },
    compileSeconds,
    samplingSeconds,
    priorReport: mmm_exports.format_prior_check(checked)
  };
}

// demo/frontend/worker.ts
self.onmessage = ({ data }) => {
  try {
    const { world } = data;
    const n = world.context_weeks;
    const date = (i) => new Date(Date.UTC(2020, 0, 6 + 7 * i)).toISOString().slice(0, 10);
    const dates = world.outcome.map((_2, i) => date(i));
    const dataset2 = { dates: dates.slice(0, n), channels: world.channels, controls: ["promotion"], x: world.spend.slice(0, n), z: world.controls.slice(0, n), y: world.outcome.slice(0, n) };
    const config = { lag: 8, seasonality: true, priorScale: 2, chains: 4, tune: 1e3, draws: 1e3, targetAccept: 0.99, seed: 42 };
    const run = sampleTymcModel(
      dataset2,
      config,
      (phase) => self.postMessage({ type: "phase", phase }),
      (event) => {
        if (event.iteration % 25 === 0) self.postMessage({ type: "progress", chain: event.chain + 1, phase: event.phase, iteration: event.iteration + 1 });
        return true;
      }
    );
    self.postMessage({ type: "phase", phase: "Forecasting the held-out weeks" });
    const columns3 = Object.fromEntries(world.channels.map((name, j) => [name, world.spend.slice(n).map((r2) => r2[j])]));
    const future = mmm_exports.dataset({ verbose: false, dates: dates.slice(n), channels: columns3, controls: { promotion: world.controls.slice(n).map((r2) => r2[0]) } });
    const scaled2 = mmm_exports.scale_like(future, run.fitted.scaled_data.scales);
    const prediction = mmm_exports.unscale(mmm_exports.predict(run.fitted, scaled2, { include_last_observations: true, seed: 142 }).expected_target, run.fitted.scaled_data.scales);
    const width = world.outcome.length - n;
    const count = prediction.values.length / width;
    const mean4 = Array.from({ length: width }, (_2, t) => {
      let s = 0;
      for (let d = 0; d < count; d++) s += prediction.values[d * width + t];
      return s / count;
    });
    const summary4 = run.fitted.result.summary;
    const rhats = summary4.map((v) => v.r_hat).filter(Number.isFinite);
    const divergences = run.fitted.result.chains.reduce((sum2, c) => sum2 + Array.from(c.divergent).filter(Boolean).length, 0);
    self.postMessage({ type: "result", mean: mean4, seconds: run.compileSeconds + run.samplingSeconds, divergences, maxRhat: rhats.length ? Math.max(...rhats) : null, draws: count });
  } catch (err) {
    self.postMessage({ type: "error", message: err instanceof Error ? err.message : String(err) });
  }
};
